lemma cLpNorm_prod_le [Finite α] {ι : Type*} {s : Finset ι} (hs : s.Nonempty) {p : ι → ℝ≥0}
    (hp : ∀ i, p i ≠ 0) (q : ℝ≥0) (hpq : ∑ i ∈ s, ((p i)⁻¹ : ℝ≥0∞) = (q : ℝ≥0∞)⁻¹) (f : ι → α → 𝕜) :
    cLpNorm q (∏ i ∈ s, f i) ≤ ∏ i ∈ s, cLpNorm (p i) (f i)
